import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as textUtils from '@/text';

export default function createNode(config, ctx) {
    // Root object
    const root = new THREE.Object3D();

    // Position / rotation / scale
    const pos = config.position || [0, 0, 0];
    const rot = config.rotation || [0, 0, 0];
    const scl = config.scale || [1, 1, 1];
    root.position.set(pos[0], pos[1], pos[2]);
    root.rotation.set(rot[0], rot[1], rot[2]);
    root.scale.set(scl[0], scl[1], scl[2]);

    // -------------------------------------------------
    // Textured plane (sprite‑style billboard)
    // -------------------------------------------------
    // Load texture (synchronously, cached)
    const imgUrl = (config.assets && config.assets.imageUrl) || '';
    const baseTexture = ctx.textureLoader(imgUrl);

    // Clone so we can adjust UVs without affecting other users
    const tex = baseTexture.clone();
    tex.needsUpdate = true;

    // Atlas region (source rect)
    const atlasInfo = config.atlasRegion || {};
    const src = atlasInfo.sourceRect || [0, 0, 512, 320]; // [x, y, w, h]
    const texWidth = tex.image?.width || 1;
    const texHeight = tex.image?.height || 1;

    // Set UV offset / repeat for the region
    tex.offset.set(src[0] / texWidth, src[1] / texHeight);
    tex.repeat.set(src[2] / texWidth, src[3] / texHeight);

    // Plane size matches aspect ratio of the region
    const aspect = src[2] / src[3];
    const planeGeo = new THREE.PlaneGeometry(aspect, 1);
    const planeMat = new THREE.MeshBasicNodeMaterial({ map: texture(tex) });
    planeMat.transparent = true;
    const planeMesh = new THREE.Mesh(planeGeo, planeMat);
    planeMesh.matrixAutoUpdate = false;
    planeMesh.updateMatrix();

    // Make it always face the camera (simple billboard by copying rotation each frame)
    // We'll store a tiny updater in userData and stop it on cleanup.
    const billboardUpdater = () => {
        if (root.parent && root.parent.camera) {
            // inverse of camera rotation so plane faces the camera
            planeMesh.quaternion.copy(root.parent.camera.quaternion);
        } else {
            planeMesh.quaternion.copy(root.quaternion);
        }
    };
    // Attach to render loop via a simple callback (client code is expected to call it)
    root.userData._billboardUpdate = billboardUpdater;

    root.add(planeMesh);

    // -------------------------------------------------
    // Text label using the font atlas (MSDF)
    // -------------------------------------------------
    let textObj = null;
    if (config.textContent && ctx.fontAtlas && typeof ctx.fontAtlas.createText === 'function') {
        // Basic style – headline size from design tokens (≈0.34 scene units)
        const style = {
            font: 'display', // refer to typographic token name
            size: 0.34,
            color: (config.colors && config.colors.ink) || '#16161d',
            align: 'center',
        };
        textObj = ctx.fontAtlas.createText(config.textContent, style);
        if (textObj) {
            // Position slightly in front of the plane to avoid Z‑fighting
            textObj.position.set(0, 0, 0.001);
            root.add(textObj);
        }
    }

    // -------------------------------------------------
    // Apply cinematic primitives (if any)
    // -------------------------------------------------
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const prim of config.cinematicPrimitives) {
            const fn = ctx.primitives[prim.name];
            if (typeof fn === 'function') {
                fn(root, prim.params);
            }
        }
    }

    // -------------------------------------------------
    // Event handler placeholder (no interactions defined)
    // -------------------------------------------------
    root.userData.handlers = {};

    // -------------------------------------------------
    // Cleanup logic
    // -------------------------------------------------
    const timelines = [];

    root.userData.cleanup = () => {
        // Kill any GSAP timelines we may have created
        timelines.forEach(t => t.kill());

        // Dispose geometry and material
        planeGeo.dispose();
        planeMat.dispose();
        tex.dispose();

        // Dispose text resources if they exist
        if (textObj) {
            if (textObj.geometry) textObj.geometry.dispose();
            if (textObj.material) {
                if (Array.isArray(textObj.material)) {
                    textObj.material.forEach(m => m.dispose());
                } else {
                    textObj.material.dispose();
                }
            }
        }

        // Remove billboard updater reference
        delete root.userData._billboardUpdate;
    };

    return root;
}
